+// ---- Q2_K: 256 elements from an 84-byte super-block. Layout: scales[16] (low 4 bits = scale,
+// high 4 bits = min), qh[16] (high 2 bits of 128 elements), ql[64] (low 2 bits), fp16 d LAST.
+// Transcribed from dequantize_row_q2_K (ggml-quants.c at 3cf03257).
+inline void dequantize_q2_K(const uint8_t* block, float* out) {
+    const float d = fp16_to_fp32(read_u16(block + 82));
+    const uint8_t* sc = block;       // 16 bytes: low nibble = scale, high nibble = min
+    const uint8_t* qh = block + 16;  // 16 bytes: 2-bit high planes
+    const uint8_t* ql = block + 32;  // 64 bytes: 2-bit low planes
+    float* y = out;
+    for (int j = 0; j < 256; j += 16) {
+        const int sl = sc[j / 16] & 0x0F;
+        const int ml = sc[j / 16] >> 4;
+        const float dl = d * (float)sl;
+        const float ml_f = d * (float)ml;
+        for (int l = 0; l < 16; ++l) {
+            const int idx = j + l;
+            const int lo = (ql[idx / 4] >> ((idx % 4) * 2)) & 3;
+            const int hi = (qh[idx / 4] >> ((idx % 4) * 2)) & 3;
+            y[l] = dl * (float)(lo | (hi << 2)) - ml_f;
+        }
+        y += 16;
+    }
+}
