-        return enabled() && held <= budget_ && incoming <= budget_ - held &&
-               entries_.size() < slots_ && bytes() <= budget_ - held - incoming;
+        if (!enabled() || held > budget_ || entries_.size() >= slots_) return false;
+        const size_t after_held = budget_ - held;
+        if (incoming > after_held) return false;
+        const size_t after_incoming = after_held - incoming;
+        return bytes() <= after_incoming;
